@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#06080e;--panel:#0b0f18;--line:#1a2532;--cyan:#5beaff;--pink:#ff4d9d;--yellow:#ffd86b;--muted:#758291;--white:#eff8ff}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% 40%,#101927 0,#080b12 48%,#05070b 100%);color:var(--white);font-family:Manrope,system-ui,sans-serif;min-height:100vh;padding:20px 24px 12px}.shell{max-width:1320px;margin:auto}.topbar{height:46px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.brand{display:flex;align-items:center;gap:10px;color:var(--white);text-decoration:none;font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:1.9px;line-height:15px}.brand-mark{width:32px;height:32px;display:grid;place-items:center;border:1px solid #45d9e7;color:var(--cyan);font:700 12px 'DM Mono';box-shadow:inset 0 0 12px #42eaff1b,0 0 12px #42eaff14}.brand-dim{color:#7b8b9b}.brand small{display:block;color:#697887;font:8px 'DM Mono';letter-spacing:1.5px;margin-top:3px}.status-pill{font:9px 'DM Mono';letter-spacing:1.4px;color:#778695;background:#0b1119;border:1px solid #1c2a35;border-radius:20px;padding:8px 13px}.status-pill i,.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#75f3ce;box-shadow:0 0 8px #75f3ce;margin-right:8px}.status-pill b{color:#75f3ce;font-weight:500;margin-left:5px}.sound-toggle{border:0;background:none;color:#91a1af;font:10px 'DM Mono';letter-spacing:1px;cursor:pointer}.sound-toggle:hover{color:var(--cyan)}
.game-wrap{position:relative;background:#090d14;border:1px solid #202d39;box-shadow:0 18px 70px #0008,0 0 45px #06182666;padding:10px}.hud{height:55px;display:flex;align-items:stretch;border:1px solid #1b2732;background:linear-gradient(90deg,#0d121b,#0a0e15);margin-bottom:9px}.hud-block{position:relative;display:flex;flex-direction:column;justify-content:center;padding:0 20px;min-width:120px;border-right:1px solid #1b2732}.hud-block .label{font:8px 'DM Mono';letter-spacing:1.4px;color:#6e7c89;margin-bottom:3px}.hud-block strong{font:700 17px 'Barlow Condensed';letter-spacing:1px;color:#e5f4fb}.wave-block{min-width:170px;padding-left:17px}.wave-block strong{font-size:21px;color:var(--cyan);display:inline-block;line-height:20px}.phase-text{position:absolute;left:53px;bottom:7px;color:#83939e;font:8px 'DM Mono';letter-spacing:1px}.score-block{min-width:175px}.score-block strong{font:14px 'DM Mono';letter-spacing:1.5px}.credit-block strong{color:var(--yellow)}.credit-block em{font:normal 13px 'DM Mono';color:#aa985f;margin-right:5px}.emp-block{min-width:155px}.emp-block strong{font:10px 'DM Mono';color:#72ecff;letter-spacing:1px}.cooldown-track{width:90px;height:2px;background:#1f3038;margin-top:5px}.cooldown-track i{display:block;height:100%;width:100%;background:var(--cyan);box-shadow:0 0 7px var(--cyan);transition:width .2s}.threat-block{margin-left:auto;border-right:0;min-width:120px;text-align:right;align-items:flex-end}.threat-block strong{font:13px 'DM Mono';color:var(--pink)}
.canvas-frame{position:relative;overflow:hidden;background:#03060b;border:1px solid #1b2935;aspect-ratio:16/8.65;max-height:calc(100vh - 270px);min-height:300px}#gameCanvas{display:block;width:100%;height:100%;touch-action:none;cursor:none}.canvas-vignette{pointer-events:none;position:absolute;inset:0;box-shadow:inset 0 0 70px #02050bbd,inset 0 0 2px 1px #8df6ff19}.canvas-tag{position:absolute;top:14px;color:#61717f;font:8px 'DM Mono';letter-spacing:1.3px}.canvas-tag b{font-weight:400;color:#9eb0bd}.tag-left{left:15px}.tag-right{right:15px}.live-dot{width:5px;height:5px;margin-right:5px}.center-overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#02050bc9,#02050b65 55%,#02050ba8);z-index:3}.hidden{display:none}.overlay-card{width:min(510px,90%);padding:30px 34px;background:linear-gradient(135deg,#0c131dcf,#090d15e8);border:1px solid #2a3d4b;box-shadow:0 12px 50px #0009,inset 0 0 25px #12313b24;position:relative}.overlay-card:before,.overlay-card:after{content:"";position:absolute;width:18px;height:18px;border-color:var(--cyan);border-style:solid}.overlay-card:before{left:-1px;top:-1px;border-width:1px 0 0 1px}.overlay-card:after{right:-1px;bottom:-1px;border-width:0 1px 1px 0}.eyebrow{font:9px 'DM Mono';letter-spacing:1.5px;color:#a6bbc5;margin-bottom:16px}.eyebrow span{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--pink);box-shadow:0 0 9px var(--pink);margin-right:8px}.overlay-card h1,.overlay-card h2{font:700 43px/.88 'Barlow Condensed',sans-serif;letter-spacing:1.2px;margin:0 0 15px;color:#f5fbff}.overlay-card h1 b{color:var(--cyan);font-weight:700}.overlay-card h2{font-size:38px}.overlay-card h2 span{color:var(--pink)}.overlay-card p{color:#a1afbb;font-size:12px;line-height:1.8;margin:0 0 21px}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:25px;padding:13px 15px;min-width:222px;color:#041014;background:var(--cyan);border:0;box-shadow:0 0 22px #51e4fb37;cursor:pointer;font:800 11px 'DM Mono';letter-spacing:1.2px;transition:transform .15s,filter .15s}.primary-button span{font-size:17px}.primary-button:hover{transform:translateY(-2px);filter:brightness(1.13)}.key-hint{margin-top:16px;color:#71818d;font:8px 'DM Mono';letter-spacing:1.1px}.key-hint i{font-style:normal;color:var(--pink);padding:0 5px}.shop-card{width:min(620px,94%);padding:24px 26px}.shop-card .eyebrow{margin-bottom:10px}.shop-card h2{font-size:33px;margin-bottom:7px}.shop-summary{font-size:11px!important;margin-bottom:15px!important}.upgrade-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:16px}.upgrade{position:relative;text-align:left;background:#0b141d;border:1px solid #263541;padding:10px 11px;min-height:66px;color:var(--white);cursor:pointer;transition:border-color .15s,background .15s}.upgrade:hover:not(:disabled){border-color:var(--cyan);background:#10212a}.upgrade:disabled{opacity:.42;cursor:not-allowed}.upgrade b{display:block;font:700 12px 'Barlow Condensed';letter-spacing:.7px}.upgrade small{display:block;color:#82939f;font:9px 'DM Mono';margin-top:4px}.upgrade em{position:absolute;right:9px;top:10px;color:var(--yellow);font:10px 'DM Mono';font-style:normal}.shop-card .primary-button{min-width:215px}.end-card{max-width:450px}.danger{color:#ff879d}.danger span{background:#ff4d6c;box-shadow:0 0 9px #ff4d6c}
.city-status{height:35px;display:flex;align-items:center;justify-content:center;gap:8px;background:#090e15;border:1px solid #1b2732;border-top:0}.building-health{height:19px;display:flex;align-items:center;gap:5px;padding:0 8px;border-right:1px solid #1c2933}.building-health:last-child{border:0}.building-health span{font:8px 'DM Mono';color:#758691;letter-spacing:.7px}.building-health .health-track{width:40px;height:3px;background:#24303a}.health-track i{display:block;height:100%;background:#78efc3;box-shadow:0 0 5px #78efc3;transition:width .3s}.controls-bar{height:52px;display:flex;align-items:center;padding:0 6px;border:1px solid #1b2732;border-top:0;background:#0a0e15}.control{display:flex;align-items:center;gap:9px;padding:0 17px;border-right:1px solid #1b2732}.control-icon{width:24px;font-size:20px;text-align:center;line-height:1}.laser-icon{color:var(--cyan)}.missile-icon{color:var(--pink);transform:rotate(-40deg)}.emp-icon{color:var(--yellow)}.control b,.heat-widget>span{display:block;font:700 9px 'Barlow Condensed';letter-spacing:1px;color:#dce7ed}.control small{display:block;margin-top:3px;color:#788894;font:8px 'DM Mono';white-space:nowrap}.control kbd{font:8px 'DM Mono';color:#b0bec6;background:#131d26;padding:2px 4px;border:1px solid #24323d}.control small i{font-style:normal;color:#e979aa}.heat-widget{margin-left:auto;display:flex;align-items:center;gap:8px;padding:0 13px}.heat-widget>span{color:#81909b}.heat-track{width:70px;height:4px;background:#222d38}.heat-track i{display:block;width:0;height:100%;background:var(--cyan);box-shadow:0 0 6px currentColor;transition:width .1s,background .2s}.heat-widget b{width:30px;color:#8da0ad;font:9px 'DM Mono'}.mobile-controls{display:none}footer{display:flex;justify-content:space-between;padding:11px 2px 0;color:#586572;font:8px 'DM Mono';letter-spacing:1px}footer i{font-style:normal;color:#3f4a54}footer b{color:var(--pink);font-size:7px;margin-left:5px}
@media(max-width:760px){body{padding:10px 9px 10px}.topbar{margin-bottom:9px;height:38px}.status-pill{display:none}.brand{font-size:14px}.sound-toggle{font-size:9px}.game-wrap{padding:6px}.hud{height:48px;margin-bottom:6px}.hud-block{padding:0 8px;min-width:0;flex:1}.hud-block .label{font-size:7px;letter-spacing:.7px}.hud-block strong{font-size:14px}.wave-block{padding-left:9px;flex:.9}.wave-block strong{font-size:18px}.phase-text{left:38px;bottom:5px;font-size:6px}.score-block{flex:1.35}.score-block strong{font-size:11px;letter-spacing:.5px}.credit-block strong{font-size:14px}.emp-block{flex:1.15}.emp-block strong{font-size:8px}.cooldown-track{width:45px}.threat-block{display:none}.canvas-frame{aspect-ratio:4/3;min-height:250px;max-height:52vh}.canvas-tag{top:9px;font-size:7px}.tag-left{left:8px}.tag-right{right:8px}.overlay-card{padding:22px 20px}.overlay-card h1{font-size:34px}.overlay-card h2{font-size:30px}.overlay-card p{font-size:10px}.key-hint{font-size:7px;line-height:1.6}.shop-card{padding:16px 14px}.shop-card .eyebrow{font-size:7px;margin-bottom:7px}.shop-card h2{font-size:27px}.shop-summary{font-size:9px!important;margin-bottom:9px!important}.upgrade-grid{gap:5px;margin-bottom:10px}.upgrade{padding:8px;min-height:58px}.upgrade b{font-size:10px}.upgrade small{font-size:7px}.upgrade em{font-size:8px;top:8px;right:7px}.primary-button{font-size:9px;padding:11px 12px;min-width:190px}.shop-card .primary-button{min-width:185px}.city-status{height:29px;gap:0;justify-content:space-around}.building-health{padding:0 4px;gap:3px}.building-health span{font-size:6px}.building-health .health-track{width:24px}.controls-bar{height:41px;padding:0}.control{padding:0 7px;gap:4px}.control-icon{font-size:16px;width:17px}.control b{font-size:8px}.control small{font-size:6px}.control kbd{font-size:6px;padding:1px 2px}.heat-widget{gap:4px;padding:0 5px}.heat-widget>span{font-size:7px}.heat-track{width:32px}.heat-widget b{font-size:7px;width:24px}.mobile-controls{display:flex;gap:6px;padding:7px 2px 1px}.mobile-fire{flex:1;border:1px solid #24404a;background:#0c1820;color:var(--cyan);padding:8px 3px;font:700 10px 'DM Mono';letter-spacing:.8px;touch-action:none}.mobile-fire small{display:block;color:#788d98;font:7px 'DM Mono';margin-top:3px}.missile-mobile{color:var(--pink);border-color:#48253a;background:#1a101a}.emp-mobile{color:var(--yellow);border-color:#483d22;background:#17160f}.mobile-fire:active{filter:brightness(1.6)}footer{font-size:6px;padding-top:8px}}
@media(max-width:380px){.control{padding:0 4px}.control-icon{display:none}.control small{font-size:5px}.heat-widget>span{display:none}.score-block{flex:1.2}.city-status{overflow:hidden}.building-health .health-track{width:19px}}

(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const W = 1000, H = 540, groundY = 462;
  const $ = id => document.getElementById(id);
  const ui = {wave:$('waveValue'),phase:$('phaseText'),score:$('scoreValue'),credits:$('creditValue'),emp:$('empValue'),empBar:$('empBar'),threats:$('threatValue'),ammo:$('ammoValue'),heat:$('heatValue'),heatBar:$('heatBar'),city:$('cityStatus'),mobileAmmo:$('mobileAmmo')};
  const overlays = {start:$('startOverlay'),shop:$('shopOverlay'),over:$('gameOverOverlay')};
  const colors = {cyan:'#62ecff',pink:'#ff58a6',yellow:'#ffd56e',green:'#73f0c4',white:'#f4fbff'};
  const buildings = [
    {x:76,w:75,h:105,name:'NORTH',hp:100,max:100}, {x:178,w:84,h:145,name:'ARC',hp:100,max:100},
    {x:291,w:70,h:90,name:'NOVA',hp:100,max:100}, {x:389,w:92,h:130,name:'CENTRAL',hp:100,max:100},
    {x:510,w:73,h:100,name:'VALE',hp:100,max:100}, {x:613,w:83,h:155,name:'ZENITH',hp:100,max:100},
    {x:726,w:75,h:114,name:'EAST',hp:100,max:100}, {x:830,w:93,h:136,name:'HARBOR',hp:100,max:100}
  ];
  const stars = Array.from({length:105},()=>({x:Math.random()*W,y:Math.random()*groundY,size:Math.random()*1.5+.25,alpha:Math.random()*.55+.12,twinkle:Math.random()*6}));
  let state = 'title', wave=1, score=0, credits=120, heat=0, overheated=false, missiles=8, empReady=true, empTimer=0, empCooldown=12, fireRate=0.16, fireTimer=0, missileRadius=62, autoInterceptors=0, spawnQueue=[], spawnTimer=0, enemies=[], shots=[], enemyShots=[], particles=[], blasts=[], beams=[], time=0, last=0, shake=0, pointer={x:500,y:250,active:false}, firing=false, muted=false, audio=null, waveKills=0;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}
  addEventListener('resize',resize); resize();
  function audioCtx(){if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();return audio}
  function tone(freq,duration,type='square',volume=.035,endFreq=null){if(muted)return;try{const a=audioCtx(),o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.setValueAtTime(freq,a.currentTime);if(endFreq)o.frequency.exponentialRampToValueAtTime(endFreq,a.currentTime+duration);g.gain.setValueAtTime(volume,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+duration);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+duration)}catch(_){}}
  function noise(duration=.14,volume=.07){if(muted)return;try{const a=audioCtx(),n=Math.floor(a.sampleRate*duration),b=a.createBuffer(1,n,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);const s=a.createBufferSource(),g=a.createGain();s.buffer=b;g.gain.value=volume;s.connect(g);g.connect(a.destination);s.start()}catch(_){}}
  function sound(kind){if(kind==='fire')tone(520,.09,'sawtooth',.018,175);if(kind==='missile')tone(155,.32,'sawtooth',.055,700);if(kind==='boom'){noise(.22,.09);tone(90,.32,'triangle',.07,35)}if(kind==='lock')tone(880,.12,'square',.025,1240);if(kind==='emp'){tone(130,.6,'sawtooth',.055,960);tone(390,.52,'triangle',.025,90)}if(kind==='split')tone(250,.2,'square',.04,620)}
  $('soundToggle').addEventListener('click',()=>{muted=!muted;$('soundToggle').innerHTML=muted?'♫ <span>SOUND OFF</span>':'♫ <span>SOUND ON</span>';if(!muted)tone(500,.08)});
  function setOverlay(which){Object.values(overlays).forEach(o=>o.classList.add('hidden'));if(which)overlays[which].classList.remove('hidden')}
  function startGame(){state='active';setOverlay(null);audioCtx();beginWave();canvas.focus()}
  $('startButton').onclick=startGame; $('restartButton').onclick=()=>{buildings.forEach(b=>b.hp=100);score=0;credits=120;wave=1;heat=0;overheated=false;missiles=8;empReady=true;empCooldown=12;fireRate=.16;missileRadius=62;autoInterceptors=0;enemies=[];shots=[];enemyShots=[];particles=[];blasts=[];waveKills=0;startGame()};
  $('nextWaveButton').onclick=()=>{wave++;beginWave()};
  function beginWave(){state='active';setOverlay(null);missiles=8+Math.min(4,Math.floor(wave/3));empReady=true;empTimer=0;waveKills=0;spawnQueue=[];const count=5+wave*2;for(let i=0;i<count;i++){let type='rocket';const r=Math.random();if(wave>=2&&r<.2)type='cluster';else if(wave>=3&&r<.38)type='drone';spawnQueue.push({type,delay:i===0?.8:Math.random()*.8+.35})}if(wave%5===0)spawnQueue.unshift({type:'boss',delay:2});spawnTimer=.45;ui.phase.textContent='INBOUND';sound('lock')}
  function liveBuildings(){return buildings.filter(b=>b.hp>0)}
  function createEnemy(type,x=null,y=-20,small=false){const target=liveBuildings();if(!target.length)return;const b=target[Math.floor(Math.random()*target.length)],sx=x===null?Math.random()*900+50:x;let hp=type==='boss'?32:type==='drone'?5:type==='cluster'?4:small?1:2;enemies.push({type,x:sx,y,vx:0,vy:0,target:b,health:hp,max:hp,phase:Math.random()*6,split:false,small,age:0,fire:1+Math.random()*1.5,drift:(Math.random()-.5)*18});}
  function beginShop(){state='shop';setOverlay('shop');const survival=Math.round(liveBuildings().length/buildings.length*100);const reward=40+Math.round(survival*.65)+wave*8;credits+=reward;$('shopSummary').textContent=`Wave ${wave} cleared · ${survival}% of the city still standing · +${reward}¢ salvage`;renderShop();ui.phase.textContent='REARM';tone(440,.18,'triangle',.04,660)}
  const upgrades=[
    {key:'repair',title:'GRID REPAIR',desc:'Restore 32 integrity to all surviving towers.',cost:75,buy:()=>buildings.forEach(b=>{if(b.hp>0)b.hp=Math.min(100,b.hp+32)})},
    {key:'laser',title:'COIL OVERDRIVE',desc:'Faster fire, +12% heat capacity.',cost:110,buy:()=>{fireRate=Math.max(.075,fireRate*.82);heat=Math.max(0,heat-12)}},
    {key:'missile',title:'WIDE-ANGLE WARHEAD',desc:'Blast radius +22, add 3 missiles.',cost:95,buy:()=>{missileRadius+=22;missiles+=3}},
    {key:'auto',title:'AUTO-INTERCEPTOR',desc:'Orbiting drone fires at threats every 2.2 sec.',cost:150,buy:()=>autoInterceptors=Math.min(3,autoInterceptors+1)},
    {key:'emp',title:'CAPACITOR BANK',desc:'EMP recharges faster and refills next wave.',cost:120,buy:()=>empCooldown=Math.max(5,empCooldown-2)},
    {key:'armor',title:'CITY SHIELDING',desc:'Restore 12 integrity to every surviving tower.',cost:65,buy:()=>buildings.forEach(b=>{if(b.hp>0)b.hp=Math.min(100,b.hp+12)})}
  ];
  function renderShop(){const grid=$('upgradeGrid');grid.innerHTML='';upgrades.forEach(u=>{const btn=document.createElement('button');btn.className='upgrade';btn.disabled=credits<u.cost;btn.innerHTML=`<b>${u.title}</b><small>${u.desc}</small><em>${u.cost}¢</em>`;btn.onclick=()=>{if(credits<u.cost)return;credits-=u.cost;u.buy();sound('lock');renderShop();updateUI()};grid.appendChild(btn)});updateUI()}
  function maybeEnd(){if(!liveBuildings().length){state='over';setOverlay('over');$('finalSummary').textContent=`You survived ${Math.max(0,wave-1)} wave${wave===2?'':'s'} · ${score.toLocaleString()} points · the city will remember.`;noise(.4,.1);return}if(state==='active'&&spawnQueue.length===0&&enemies.length===0&&enemyShots.length===0)beginShop()}
  function buildingAt(x){return buildings.filter(b=>b.hp>0).sort((a,b)=>Math.abs(a.x+a.w/2-x)-Math.abs(b.x+b.w/2-x))[0]}
  function spawnBurst(x,y,color,n=12){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=Math.random()*170+35;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.55,max:.8,color,size:Math.random()*2.2+.7})}}
  function destroyEnemy(e,award=true){const index=enemies.indexOf(e);if(index<0)return;enemies.splice(index,1);const col=e.type==='drone'?colors.cyan:e.type==='boss'?colors.pink:colors.yellow;spawnBurst(e.x,e.y,col,e.type==='boss'?38:14);blasts.push({x:e.x,y:e.y,r:0,max:e.type==='boss'?42:17,life:.22});sound('boom');shake=Math.max(shake,e.type==='boss'?9:3);if(award){score+=e.type==='boss'?1200:e.type==='drone'?220:100;credits+=e.type==='boss'?55:12;waveKills++}}
  function hitBuilding(b,damage){if(!b||b.hp<=0)return;b.hp=Math.max(0,b.hp-damage);spawnBurst(b.x+b.w/2,groundY-6,colors.pink,15);shake=Math.max(shake,7);sound('boom');if(b.hp===0){credits+=5;score+=100}}
  function fireLaser(){if(state!=='active'||overheated||fireTimer>0)return;fireTimer=fireRate;heat=Math.min(100,heat+9);if(heat>=100){overheated=true}const gun=pointer.x<W/2?250:750,origin={x:gun,y:groundY-62};shots.push({x:origin.x,y:origin.y,tx:pointer.x,ty:pointer.y,life:.13,max:.13});beams.push({x1:origin.x,y1:origin.y,x2:pointer.x,y2:pointer.y,life:.12,max:.12});for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];if(Math.hypot(e.x-pointer.x,e.y-pointer.y)<(e.type==='boss'?34:17)){e.health-=e.type==='boss'?2:2;spawnBurst(pointer.x,pointer.y,colors.cyan,3);if(e.health<=0)destroyEnemy(e);break}}sound('fire')}
  function fireMissile(){if(state!=='active'||missiles<=0)return;missiles--;const gun=pointer.x<W/2?250:750;shots.push({x:gun,y:groundY-62,tx:pointer.x,ty:pointer.y,life:.75,max:.75,missile:true});sound('missile');updateUI()}
  function emp(){if(state!=='active'||!empReady)return;empReady=false;empTimer=empCooldown;for(const e of [...enemies])destroyEnemy(e);enemyShots=[];blasts.push({x:500,y:250,r:0,max:850,life:.8,emp:true});for(let i=0;i<80;i++)spawnBurst(Math.random()*W,Math.random()*groundY,colors.cyan,1);sound('emp');shake=11;updateUI()}
