  for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.life-=dt;if(s.life<=0){if(s.missile){blasts.push({x:s.tx,y:s.ty,r:0,max:missileRadius,life:.42});spawnBurst(s.tx,s.ty,colors.pink,24);sound('boom');shake=Math.max(shake,5);for(const e of [...enemies])if(Math.hypot(e.x-s.tx,e.y-s.ty)<missileRadius+(e.type==='boss'?20:0)){e.health-=e.type==='boss'?10:10;if(e.health<=0)destroyEnemy(e)}}shots.splice(i,1)}}
