  for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy=p.vy*Math.pow(.08,dt)+18*dt;if(p.life<=0)particles.splice(i,1)}
