  ctx.save();ctx.globalAlpha=.22;ctx.strokeStyle='#297788';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(500,267,330,56,0,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.ellipse(500,267,380,70,0,0,Math.PI*2);ctx.stroke();ctx.restore();
}
