    ctx.fillStyle=b.hp>0?'#0c1a25':'#1a1018';ctx.fillRect(b.x+5,top+7,b.w-10,15);ctx.fillStyle=b.hp>0?'#76f1ff':'#a64263';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText(['N-01','A R C','NOVA','CENTRAL','V A L E','ZENITH','EAST-9','HARBOR'][i],b.x+b.w/2,top+18);
    for(let yy=top+31;yy<groundY-10;yy+=17)for(let xx=b.x+9;xx<b.x+b.w-5;xx+=13){const on=((Math.floor(xx/13)*7+Math.floor(yy/17)*11+i)%5)!==0;ctx.fillStyle=b.hp<=0?'#401c31':on?(i%3===0?'#ffd569':'#48dcea'):'#132531';ctx.globalAlpha=b.hp<=0?.3:.62;ctx.fillRect(xx,yy,5,7)}ctx.globalAlpha=1;
